-- ── Malnutrition/anaemia screening — all children brought to clinic ───────────
-- Per §12: Paediatric Nursing → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Paediatric Nursing','Nutrition Assessment','The categories of children who should be checked for malnutrition and anaemia include:','Children with diarrhoea','Children with feeding problems','All children brought to clinic','Children with chronic illness causing weight loss','C','Kenya IMNCI protocol mandates that ALL sick children brought to the clinic be routinely assessed for malnutrition and anaemia — not only selected groups — to ensure no case is missed (Kenya IMNCI chart booklet; MOH Kenya Basic Paediatric Protocols).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Paediatric Nursing','Nutrition Assessment','The categories of children who should be checked for malnutrition and anaemia include:','Children with diarrhoea','Children with feeding problems','All children brought to clinic','Children with chronic illness causing weight loss','C','Universal IMNCI screening for malnutrition and anaemia at every sick-child visit ensures early detection; BScN nurses lead nutritional surveillance programmes and interpret MUAC/weight-for-height findings (Kenya IMNCI; MOH Kenya Basic Paediatric Protocols).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Schistosoma haematobium — urogenital damage ───────────────────────────────
-- Per §12: Medical-Surgical Nursing → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Medical-Surgical Nursing','Parasitic Infections','Infection with this parasite can cause extensive damage to human urogenital structures:','Ascaris lumbricoides','Schistosoma haematobium','Toxoplasma gondii','Schistosoma mansoni','B','Schistosoma haematobium is the species causing urinary schistosomiasis, infecting the vesical venous plexus and causing bladder and urogenital pathology including haematuria, hydronephrosis and bladder cancer (Kenya NTD/parasitology guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Medical-Surgical Nursing','Parasitic Infections','Infection with this parasite can cause extensive damage to human urogenital structures:','Ascaris lumbricoides','Schistosoma haematobium','Toxoplasma gondii','Schistosoma mansoni','B','S. haematobium causes haematuria (classic painless), urinary obstruction and bladder carcinoma with chronic infection. BScN nurses integrate schistosomiasis screening into community health programmes in endemic regions (Kenya NTD guidelines; Brunner & Suddarth).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Herd immunity — high percentage immune ────────────────────────────────────
-- Per §12: Community Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Epidemiology','Herd immunity exists in a community when:','A high percentage of people are immune to an infection','The incidence of the disease decreases to a very low level','Vaccination is stopped in a well-vaccinated community','Both dead and live antigens are used to immunise','A','Herd immunity exists when a sufficiently high proportion of the population is immune to an infection, reducing transmission and protecting unimmunised individuals (Kenya EPI/immunisation guidelines; epidemiology).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Epidemiology','Herd immunity exists in a community when:','A high percentage of people are immune to an infection','The incidence of the disease decreases to a very low level','Vaccination is stopped in a well-vaccinated community','Both dead and live antigens are used to immunise','A','Herd immunity threshold varies by R0 (measles ~95%, polio ~80-85%); BScN nurses monitor vaccination coverage data, identify immunity gaps and plan catch-up campaigns (Kenya EPI; WHO immunisation guidelines; epidemiology).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Bipolar I nursing intervention — structured environment ───────────────────
-- Per §12: Mental Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Mental Health Nursing','Mood Disorders','A nursing intervention for a male client with bipolar I disorder should include:','Designing activities requiring maintenance of contact with reality','Providing a structured environment','Engaging the client in current affairs conversation','Touching the client to provide assurance','B','Manic clients in bipolar I disorder require a structured, low-stimulus environment to reduce distractibility, hyperactivity and impulsive behaviour; overstimulating activities worsen the manic episode (psychiatric nursing/Brunner & Suddarth).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Mental Health Nursing','Mood Disorders','A nursing intervention for a male client with bipolar I disorder should include:','Designing activities requiring maintenance of contact with reality','Providing a structured environment','Engaging the client in current affairs conversation','Touching the client to provide assurance','B','Structure reduces mania-related decision-making impulsivity and risk; BScN nurses apply evidence-based milieu therapy, set consistent limits, coordinate interdisciplinary care and educate families on relapse triggers (psychiatric nursing; Kenya Mental Health guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Labile affect — rapid abrupt changes in emotional feeling ─────────────────
-- Per §12: Mental Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Mental Health Nursing','Mental Status Examination','Rapid and abrupt changes in emotional feeling describe:','Rapid affect','Restricted affect','Labile affect','Inappropriate affect','C','Labile affect denotes rapid, abrupt, uncontrollable shifts in emotional expression not proportional to the stimulus; seen in mania, pseudobulbar palsy and some personality disorders (mental health assessment/psychiatric nursing texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Mental Health Nursing','Mental Status Examination','Rapid and abrupt changes in emotional feeling describe:','Rapid affect','Restricted affect','Labile affect','Inappropriate affect','C','BScN nurses document affect objectively in the MSE: labile (unstable), blunted (reduced intensity), flat (absent), restricted (mildly reduced), inappropriate (incongruent with thought content); accurate documentation guides diagnosis (DSM-5; Stuart Psychiatric Nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

