VALUES('KRCHN','Paper II','Community Health Nursing','Home Visiting','Activities during the post-visit phase of a home visit include:','Developing a future follow-up care plan','Integrating the patient into the community','Transferring patient care to another agency','Sharing the report of home visit with relevant authorities','A','The post-visit (evaluation) phase of a home visit includes documenting findings and developing a future follow-up care plan based on assessment outcomes (Kenya community health nursing guidelines; KMTC curriculum).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Home Visiting','Activities during the post-visit phase of a home visit include:','Developing a future follow-up care plan','Integrating the patient into the community','Transferring patient care to another agency','Sharing the report of home visit with relevant authorities','A','Post-visit activities: recording, analysis of findings and care plan development are essential for continuity; BScN nurses also evaluate goal achievement and link families to community resources (Kenya community health nursing; MOH Kenya community health strategy).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Abortive polio symptom — sore throat ──────────────────────────────────────
-- Per §12: Communicable Disease → Paper II (Community Health) both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Communicable Diseases','The following is a symptom of abortive polio:','Muscle spasm','Sore throat','Stiff neck','Back pain','B','Abortive (minor illness) poliomyelitis presents with non-specific symptoms including fever, sore throat, malaise and headache without CNS involvement; it accounts for ~5% of polio infections (Kenya EPI/communicable disease guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Communicable Diseases','The following is a symptom of abortive polio:','Muscle spasm','Sore throat','Stiff neck','Back pain','B','Abortive polio (minor illness): fever, sore throat, vomiting; no paralysis. Non-paralytic: adds meningism. Paralytic: LMN flaccid paralysis. BScN nurses apply this classification in AFP surveillance and notification (Kenya EPI; WHO polio eradication guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Depression — indecisiveness and poor concentration significant ────────────
-- Per §12: Mental Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Mental Health Nursing','Mood Disorders','Which statement is true in reference to depression?','It can only be confirmed if a patient has lost a relative, job or something valuable','The illness obviously runs along familial lines','Indecisiveness and poor concentration are significant in its diagnosis','In children and adolescents it is not significant','C','Indecisiveness and impaired concentration are core DSM-5 diagnostic criteria for a major depressive episode; loss is a risk factor but not a diagnostic requirement, and depression is highly significant in children and adolescents (DSM-5; Kenya Mental Health guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Mental Health Nursing','Mood Disorders','Which statement is true in reference to depression?','It can only be confirmed if a patient has lost a relative, job or something valuable','The illness obviously runs along familial lines','Indecisiveness and poor concentration are significant in its diagnosis','In children and adolescents it is not significant','C','DSM-5 MDE requires ≥5 of 9 criteria for ≥2 weeks; indecisiveness and concentration difficulties are among them. BScN nurses apply validated screening tools (PHQ-9) and distinguish unipolar from bipolar depression before prescribing antidepressants (DSM-5; Stuart).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

