VALUES('KRCHN','Paper II','Research & Statistics','Biostatistics','Research descriptive statistics refers to:','An estimate of population parameters from sample data','A description of the patterns and specific trends in a dataset','Examination of one variable at a time','Testing hypothesis','B','Descriptive statistics summarise and describe patterns and trends in a dataset using measures of central tendency and dispersion; inferential statistics extend findings to a population (Polit & Beck; nursing research texts).','hard',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Research & Evidence-Based Practice','Biostatistics','Research descriptive statistics refers to:','An estimate of population parameters from sample data','A description of the patterns and specific trends in a dataset','Examination of one variable at a time','Testing hypothesis','B','Descriptive statistics (frequency, mean, SD, range) characterise a sample; inferential statistics (t-tests, chi-square, ANOVA) generalise to populations. BScN nurses interpret descriptive data in audit reports and quality improvement cycles (Polit & Beck; nursing research).','hard',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Disaster management cycle — mitigation, preparedness, response, recovery ──
-- Per §12: Community Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Disaster Management','The cycle of disaster consists of the following components:','Mitigation, Preparedness, Response, Recovery','Preparedness, vulnerability assessment, risk assessment, recovery','None of the above','Mitigation, risk assessment, response and recovery','A','The disaster management cycle comprises four phases: Mitigation (reduce risk), Preparedness (plan and train), Response (immediate action), Recovery (restoration) (Kenya disaster management framework; community health nursing texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Disaster Management','The cycle of disaster consists of the following components:','Mitigation, Preparedness, Response, Recovery','Preparedness, vulnerability assessment, risk assessment, recovery','None of the above','Mitigation, risk assessment, response and recovery','A','BScN nurses engage all four phases: lead mitigation advocacy, coordinate preparedness training, triage in response, and plan community recovery. This cycle frames nursing roles in Kenya''s National Disaster Management framework (Kenya NDM Act; community health nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

