-- ── Health education — increases knowledge and attitude ──────────────────────
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Health Education','The importance of health education in inspiring behaviour change is that it:','Helps to increase learning and skills','Stimulates community to take ownership','Increases understanding and coping','Increases in knowledge and attitude of the people','D','Health education promotes behaviour change primarily by increasing the knowledge and attitudes of people — the foundational KAP (knowledge-attitude-practice) model underpinning all health education programmes (MOH Kenya health promotion guidelines; community health nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Health Education','The importance of health education in inspiring behaviour change is that it:','Helps to increase learning and skills','Stimulates community to take ownership','Increases understanding and coping','Increases in knowledge and attitude of the people','D','KAP model: knowledge change → attitude shift → practice change. BScN nurses design needs-based, culturally appropriate health education interventions and evaluate impact using pre/post KAP assessments (MOH Kenya health promotion guidelines; Ewles & Simnett).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Prenatal maternal factors — infections, use of drugs ─────────────────────
-- Per §12: Paediatric Nursing → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Paediatric Nursing','Growth and Development','Maternal factors affecting growth and development during the prenatal period include:','Infections and use of drugs','Smoking and faulty placental implantation','Number of children and use of drugs','Malposition and alcoholism','A','Maternal infections (rubella, CMV, toxoplasma) and drug use (teratogens) during the prenatal period are the primary maternal factors that adversely affect fetal growth and development (Kenya Basic Paediatric Protocols; child health texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Paediatric Nursing','Growth and Development','Maternal factors affecting growth and development during the prenatal period include:','Infections and use of drugs','Smoking and faulty placental implantation','Number of children and use of drugs','Malposition and alcoholism','A','TORCH infections and teratogenic drugs are the key modifiable prenatal risk factors; BScN nurses counsel pre-conception patients on rubella immunisation, alcohol/drug avoidance and infection screening at first ANC contact (Kenya ANC guidelines; Myles).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

