VALUES('BScN','Paper II','Community Health Nursing','Communicable Diseases','Communicable disease control measures at individual and village level include:','Increase immunisation coverage and environmental manipulation','Emphasise on water protection and purification','Completing immunisation and protection of springs and wells','Participate in vector and reservoir control and immunisation coverage','C','BScN nurses coordinate CHV training on immunisation completion and WASH (water, sanitation and hygiene) interventions at village level — the two most impactful individual-level communicable disease control strategies (MOH Kenya community health strategy; Kenya EPI).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Health promotion role — resource person ───────────────────────────────────
-- Per §12: Community Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Health Education','When developing health promotion plans with clients, the nurse educator should take the role of:','Promoter','Counsellor','Resource person','Advisor','C','When developing health promotion plans with clients, the nurse acts as a resource person — supplying information, resources and evidence to support client-driven decision-making rather than directing clients (health promotion/community health nursing; Ewles & Simnett).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Health Education','When developing health promotion plans with clients, the nurse educator should take the role of:','Promoter','Counsellor','Resource person','Advisor','C','The resource person role preserves client autonomy and aligns with the empowerment approach; BScN nurses distinguish this from the expert/prescriptive role in therapeutic settings (Ewles & Simnett health promotion approaches; MOH Kenya health promotion guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Democratic leadership — takes into account others' views ─────────────────
-- Per §12: Management → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Health Systems & Management','Leadership Styles','The style of leadership that takes into account other people''s views, opinions and ideas is:','Laissez-faire','Democratic','Autocratic','People-oriented','B','Democratic (participative) leadership solicits and incorporates group members'' views, opinions and ideas before decision-making, fostering ownership and team morale (nursing management/leadership texts).','hard',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Nursing Management & Leadership','Leadership Styles','The style of leadership that takes into account other people''s views, opinions and ideas is:','Laissez-faire','Democratic','Autocratic','People-oriented','B','Democratic leadership improves staff satisfaction and quality outcomes in stable, skilled teams; less effective in emergencies. BScN nurses distinguish this from transactional and transformational styles (Lewin''s leadership styles; nursing management leadership texts).','hard',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── BMI 23 — normal weight ────────────────────────────────────────────────────
-- Per §12: Community Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Nutrition','A body mass index (BMI) of 23 kg/m² is considered to be:','Obese','Overweight','Normal weight','Underweight','C','WHO/MOH Kenya BMI classification: underweight <18.5, normal 18.5–24.9, overweight 25–29.9, obese ≥30 kg/m²; a BMI of 23 falls in the normal range (Kenya MOH nutrition guidelines; WHO).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Nutrition','A body mass index (BMI) of 23 kg/m² is considered to be:','Obese','Overweight','Normal weight','Underweight','C','BMI is a population-level screening tool; BScN nurses apply it in community nutrition assessments alongside waist circumference and dietary intake to give a complete nutritional picture (Kenya MOH nutrition guidelines; WHO).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Measles complication — diarrhoea ─────────────────────────────────────────
-- Per §12: Community Health/Paediatric → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Communicable Diseases','The following is a complicated sign or symptom of measles disease:','Fever','Coryza','Coughing','Diarrhoea','D','Fever, coryza and cough are the three classical (uncomplicated) features of measles; diarrhoea indicates a complication of measles and warrants close monitoring and management (Kenya IMNCI/Basic Paediatric Protocols; EPI guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Communicable Diseases','The following is a complicated sign or symptom of measles disease:','Fever','Coryza','Coughing','Diarrhoea','D','Measles complications: pneumonia, diarrhoea, otitis media, encephalitis and malnutrition (immunosuppression). BScN nurses monitor for these during outbreak response and apply integrated management for measles with complications (Kenya IMNCI; MOH Kenya EPI).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Primary disease prevention — immunisation, balanced diet, exercise ────────
-- Per §12: Community Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Levels of Prevention','Primary disease prevention involves:','Immunisation, screening for cervical cancer, good nutrition','Early treatment, regular medical check-ups, mass treatment','Screening for cervical cancer, early treatment, immunisation','Immunisation, eating a balanced diet, regular exercise','D','Primary prevention acts before disease occurs: immunisation, eating a balanced diet and regular exercise prevent disease development; screening and early treatment are secondary prevention (Kenya community health/epidemiology; levels of prevention).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Levels of Prevention','Primary disease prevention involves:','Immunisation, screening for cervical cancer, good nutrition','Early treatment, regular medical check-ups, mass treatment','Screening for cervical cancer, early treatment, immunisation','Immunisation, eating a balanced diet, regular exercise','D','Leavell and Clark''s levels: primary (health promotion + specific protection), secondary (early diagnosis + prompt treatment), tertiary (disability limitation + rehabilitation). BScN nurses design programmes at each level (Park''s; community health nursing; Kenya KEPH).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Vulnerability analysis — mitigation phase ────────────────────────────────
