VALUES('KRCHN','Paper II','Community Health Nursing','Disaster Management','Vulnerability analysis comes in which part of the disaster management cycle?','Mitigation','Recovery','Preparedness','Response','A','Vulnerability/risk analysis is conducted during the mitigation phase to identify risks and implement measures to reduce their likelihood or impact before a disaster event (Kenya disaster management/community health texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Disaster Management','Vulnerability analysis comes in which part of the disaster management cycle?','Mitigation','Recovery','Preparedness','Response','A','Mitigation phase tools include hazard mapping, vulnerability assessment and risk reduction strategies; BScN nurses use community health assessments to identify at-risk populations (Kenya NDM framework; community health nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Measles vaccine wastage factor — 1/2 ─────────────────────────────────────
-- Per §12: Community Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Community Health Nursing','Immunisation','The wastage factor for measles vaccine is:','1/5','1/3','1/2','1/4','C','Measles is a lyophilised multi-dose vaccine reconstituted in small volumes with a high wastage allowance of 50% (wastage factor = 1/2) under Kenya EPI vaccine management and quantification guidelines (Kenya EPI; MOH Kenya cold-chain guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Community Health Nursing','Immunisation','The wastage factor for measles vaccine is:','1/5','1/3','1/2','1/4','C','Wastage factor is used in vaccine quantification: doses needed = target population × coverage ÷ (1 – wastage factor). BScN nurses apply EPI logistics principles in supply chain management and forecasting for outreach sessions (Kenya EPI; MOH Kenya cold-chain guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

