VALUES('BScN','Paper II','Community Health Nursing','Occupational Health','The main objective of an occupational health programme is:','To prevent health problems due to normal working conditions','To promote and maintain the highest degree of physical, mental and social health of workers','To assist the injured and disabled for rehabilitation and treatment','To protect workers from factors adverse to their health','B','WHO/ILO 1950 joint committee definition covers promotion, protection and placement — a comprehensive mandate. BScN occupational health nurses design programmes spanning primary, secondary and tertiary prevention for workplace populations (Kenya OSH Act; occupational health texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Neuroleptics — major tranquillisers blocking dopamine ────────────────────
-- Per §12: Pharmacology → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','CNS Pharmacology','Neuroleptics are:','Minor tranquillisers with mild calming effects on neurotic patients','Major tranquillisers which block dopamine receptors producing calming effects','Mood stabilisers that elevate mood of a depressed patient','Antidepressants','B','Neuroleptics (antipsychotics) are major tranquillisers that block dopamine D2 receptors in the mesolimbic system, reducing psychotic symptoms and producing a calming effect (BNF; Brunner & Suddarth pharmacology).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','CNS Pharmacology','Neuroleptics are:','Minor tranquillisers with mild calming effects on neurotic patients','Major tranquillisers which block dopamine receptors producing calming effects','Mood stabilisers that elevate mood of a depressed patient','Antidepressants','B','Neuroleptics block D2 receptors; atypicals also block 5-HT2A. Adverse effects: EPSEs, metabolic syndrome, NMS. BScN nurses monitor AIMS, fasting glucose, lipids and weight in patients on long-term antipsychotics (BNF; psychiatric nursing pharmacology).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

