VALUES('KRCHN','Paper I','Medical-Surgical Nursing','Gastrointestinal Procedures','Gastrointestinal decompression involves:','Gastrostomy tube suction to remove abdominal content','Insertion of a tube in the ileocaecal valve','Insertion of a trocar in the abdominal cavity','Insertion of a nasogastric tube to remove gas and fluid','D','Gastrointestinal decompression is the insertion of a nasogastric or intestinal tube to remove accumulated gas and fluid from the GI tract, relieving distension and obstruction (Brunner & Suddarth Medical-Surgical Nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Medical-Surgical Nursing','Gastrointestinal Procedures','Gastrointestinal decompression involves:','Gastrostomy tube suction to remove abdominal content','Insertion of a tube in the ileocaecal valve','Insertion of a trocar in the abdominal cavity','Insertion of a nasogastric tube to remove gas and fluid','D','NG decompression indications: paralytic ileus, bowel obstruction, post-operative abdominal surgery. BScN nurses verify placement, maintain patency, record drainage and monitor for complications of prolonged tube use (Brunner & Suddarth; surgical nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Benztropine — for EPS from antipsychotic toxicity ────────────────────────
-- Per §12: Pharmacology → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Pharmacology','CNS Pharmacology','A schizophrenic patient has been treated with haloperidol, loxapine, thiothixene and lithium and shows signs of poisoning. What should be tried?','Benztropine','Molindone','Clozapine','Trifluoperazine','A','Haloperidol, loxapine and thiothixene are typical antipsychotics causing extrapyramidal/dystonic reactions in overdose; benztropine is the anticholinergic drug of choice to reverse these EPSEs (BNF; Brunner & Suddarth pharmacology).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Pharmacology','CNS Pharmacology','A schizophrenic patient has been treated with haloperidol, loxapine, thiothixene and lithium and shows signs of poisoning. What should be tried?','Benztropine','Molindone','Clozapine','Trifluoperazine','A','Benztropine (anticholinergic) reverses acute dystonia and drug-induced parkinsonism from typical antipsychotics; IV/IM route for acute reactions. BScN nurses assess for NMS separately (fever + rigidity + autonomic instability) which requires different management (BNF; psychiatric nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Directing patients — ensures smooth client flow ───────────────────────────
-- Per §12: Management → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Health Systems & Management','Nursing Management','The following is a factor that ensures a smooth flow of clients in a health centre:','Soothing patients','Directing patients','Timely payments','Observing punctuality','B','Directing/guiding patients to the appropriate service points in the correct sequence ensures an orderly, smooth client flow through the health facility, reducing waiting times and improving patient experience (nursing management texts; MOH Kenya facility management).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Nursing Management & Leadership','Nursing Management','The following is a factor that ensures a smooth flow of clients in a health centre:','Soothing patients','Directing patients','Timely payments','Observing punctuality','B','Patient flow management reduces bottlenecks; BScN nurses as charge nurses implement triage systems, signage, CHV coordination and lean principles to optimise client flow and patient safety (MOH Kenya quality improvement standards; nursing management texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

