VALUES('BScN','Paper II','Nursing Management & Leadership','Nursing Education','Non-projected teaching aids include:','Diagrams, videos, slides','Slides, videos, pictures','Flipcharts, slides, pictures','Real objects, handouts, pictures','D','Non-projected aids are ideal for low-resource community health education settings. BScN nurses select teaching aids based on audience literacy, group size, available resources and learning objectives (nursing education; MOH Kenya health education guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Mood-congruent psychosis — delusion of guilt, poverty, grandiosity ─────────
-- Per §12: Mental Health → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Mental Health Nursing','Mood Disorders','The following are mood-congruent psychotic features in a depressed patient:','Delusion of murder, erotomania, delusion of guilt','Delusion of guilt, delusion of poverty, erotomania','Delusion of guilt, delusion of poverty, delusion of grandiosity','Delusion of persecution, delusion of grandiosity, delusion of guilt','C','Mood-congruent psychotic features in depression carry depressive themes — delusions of guilt (unworthiness) and poverty are congruent with depressed mood; delusion of grandiosity is atypically listed here as the source document intended the group of depressive-themed delusions (DSM-5; psychiatric nursing texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Mental Health Nursing','Mood Disorders','The following are mood-congruent psychotic features in a depressed patient:','Delusion of murder, erotomania, delusion of guilt','Delusion of guilt, delusion of poverty, erotomania','Delusion of guilt, delusion of poverty, delusion of grandiosity','Delusion of persecution, delusion of grandiosity, delusion of guilt','C','Mood-congruent vs mood-incongruent distinction guides prognosis and treatment; BScN nurses document psychotic features accurately in MSE and communicate findings during interdisciplinary rounds (DSM-5; Stuart Psychiatric Nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Pre-op fear/anxiety — need for increased anaesthesia ─────────────────────
-- Per §12: Surgical Nursing → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Surgical Nursing','Pre-operative Care','Pre-operative fear and anxiety can lead to:','Reduced need for psychological support','Need for increased anaesthesia','Increased speed of recovery','Need for reduced postoperative pain management','B','Preoperative fear and anxiety raise sympathetic activity and catecholamine levels, increasing anaesthetic requirements during surgery; this is well established in Brunner & Suddarth perioperative nursing.','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Surgical Nursing','Pre-operative Care','Pre-operative fear and anxiety can lead to:','Reduced need for psychological support','Need for increased anaesthesia','Increased speed of recovery','Need for reduced postoperative pain management','B','Preoperative psychological preparation (education, breathing exercises, therapeutic communication) reduces anxiety and anaesthetic requirements, improving outcomes. BScN nurses implement evidence-based preoperative anxiety interventions (Brunner & Suddarth; surgical nursing EBP).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Diabetic control before conception — reduces congenital anomalies ─────────
-- Per §12: Midwifery → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Midwifery','Diabetes in Pregnancy','Diabetic control is important before conception to reduce the incidence of:','Diabetic ketoacidosis','Congenital anomalies','Maternal nephropathy','Maternal retinopathy','B','Pre-conception glycaemic control (HbA1c <53 mmol/mol) reduces the risk of congenital anomalies linked to first-trimester hyperglycaemia, particularly cardiac defects and neural tube defects (Myles; Kenya MOH diabetes-in-pregnancy guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Midwifery','Diabetes in Pregnancy','Diabetic control is important before conception to reduce the incidence of:','Diabetic ketoacidosis','Congenital anomalies','Maternal nephropathy','Maternal retinopathy','B','Organogenesis occurs in weeks 3–8 — before many women know they are pregnant; pre-conception HbA1c optimisation is the single most impactful intervention. BScN nurses lead pre-conception counselling for women with known diabetes (Myles; MOH Kenya diabetes-in-pregnancy guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Purpose of emergency assessment — establish client database ───────────────
-- Per §12: Management/Nursing Process → Paper II both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper II','Health Systems & Management','Nursing Process','The purpose of emergency assessment is to:','Delegate nursing responsibility','Teach the client about their health','Make a diagnostic conclusion','Establish a database concerning the client','D','The purpose of the nursing assessment phase — including emergency assessment — is to systematically collect and organise data to establish a comprehensive database about the client, on which care planning is based (nursing process texts; Brunner & Suddarth).','hard',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper II','Nursing Management & Leadership','Nursing Process','The purpose of emergency assessment is to:','Delegate nursing responsibility','Teach the client about their health','Make a diagnostic conclusion','Establish a database concerning the client','D','Assessment is the first step of the nursing process; the database drives diagnosis, planning, intervention and evaluation. BScN nurses use both subjective and objective data, including electronic health records, to build comprehensive client profiles (nursing process texts; Brunner & Suddarth).','hard',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Oligohydramnios — associated with polycystic kidney ─────────────────────
-- Per §12: Midwifery → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Midwifery','Antenatal Complications','Oligohydramnios is associated with:','Hydrocephalus','Omphalocele','Sacral agenesis','Polycystic kidney disease','D','Oligohydramnios results from reduced fetal urine output, most commonly associated with fetal renal anomalies such as polycystic/dysplastic kidneys and renal agenesis (Potter sequence) (Myles Textbook for Midwives; obstetric texts).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Midwifery','Antenatal Complications','Oligohydramnios is associated with:','Hydrocephalus','Omphalocele','Sacral agenesis','Polycystic kidney disease','D','Oligohydramnios: AFI <5 cm or deepest pocket <2 cm on USS. Causes: renal agenesis/dysplasia, PPROM, post-dates, IUGR. BScN nurses recognise USS findings and coordinate obstetric management (Myles; MOH Kenya ANC guidelines).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

-- ── Eustachian tube — causes middle ear fluid accumulation if blocked ─────────
-- Per §12: Medical-Surgical Nursing → Paper I both cadres
INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('KRCHN','Paper I','Medical-Surgical Nursing','ENT Disorders','A patient with repeated colds and ear infections has fluid accumulation in the middle ear due to blockage of the:','Utricle','Saccule','Eustachian tube','External ear','C','Blockage of the Eustachian tube prevents middle ear drainage and ventilation, causing fluid accumulation (glue ear/otitis media with effusion) — a common complication of recurrent upper respiratory tract infections (Brunner & Suddarth; ENT nursing).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;

INSERT INTO questions (cadre,paper,unit,topic,stem,option_a,option_b,option_c,option_d,correct_option,rationale,difficulty,exam_year,status,contributor_id)
VALUES('BScN','Paper I','Medical-Surgical Nursing','ENT Disorders','A patient with repeated colds and ear infections has fluid accumulation in the middle ear due to blockage of the:','Utricle','Saccule','Eustachian tube','External ear','C','Eustachian tube dysfunction impairs pressure equalisation; chronic otitis media with effusion causes conductive hearing loss. BScN nurses assess hearing, refer for audiometry and educate on nasal decongestants and follow-up (Brunner & Suddarth; ENT nursing EBP).','easy',2021,'approved',NULL)ON CONFLICT(stem,cadre)DO NOTHING;
